// OWNER: INTEGRATOR
// FROZEN after the v2 skeleton. Feature workers do not edit this file.
// Need a new event or field? Note it; the integrator adds it.
//
// Hardcore: no story mode, no checkpoints.
// Cross-module calls go through the bus, ctx, or pure data
// (this file, balance.js, lines.js, characters.js). Do not import another
// workstream's runtime module. Allies may import actors/kits.js — that is
// the shared kit API, not the player controller.

export const BUILD_TAG = 'v2';

/** @enum {string} */
export const TEAMS = Object.freeze({
  PLAYER: 'player',
  ALLY: 'ally',
  BOSS: 'boss',
  NEUTRAL: 'neutral',
});

/**
 * @enum {string}
 * `paused` overlays intro or fight. Resume returns to `pauseFrom`.
 */
export const GAME_STATES = Object.freeze({
  TITLE: 'title',
  DISCLAIMER: 'disclaimer',
  SELECT: 'select',
  INTRO: 'intro',
  FIGHT: 'fight',
  BANNED: 'banned',
  CUTSCENE: 'cutscene',
  THEATER: 'theater',
  CREDITS: 'credits',
  PAUSED: 'paused',
});

/**
 * Bus event names. Values are the stable wire strings — do not rename them.
 * v1 names are unchanged. v2 appends the combat / juice events below.
 */
export const EVENTS = Object.freeze({
  /** @type {'state_change'} payload StateChange */
  STATE_CHANGE: 'state_change',
  /** @type {'fight_start'} payload {charId:string} */
  FIGHT_START: 'fight_start',
  /** @type {'fight_reset'} payload {charId:string} */
  FIGHT_RESET: 'fight_reset',
  /** @type {'phase_change'} payload PhaseChange */
  PHASE_CHANGE: 'phase_change',
  /** @type {'hit'} payload HitEvent */
  HIT: 'hit',
  /** @type {'hit_stop'} payload {ms:number} */
  HIT_STOP: 'hit_stop',
  /** @type {'flask_used'} payload FlaskEvent */
  FLASK_USED: 'flask_used',
  /** @type {'flask_interrupted'} payload FlaskEvent */
  FLASK_INTERRUPTED: 'flask_interrupted',
  /** @type {'perfect_guard'} payload {id?:string} */
  PERFECT_GUARD: 'perfect_guard',
  /** @type {'guard_start'} payload {id:string} */
  GUARD_START: 'guard_start',
  /** @type {'guard_end'} payload {id:string} */
  GUARD_END: 'guard_end',
  /** @type {'player_death'} payload PlayerDeath */
  PLAYER_DEATH: 'player_death',
  /** @type {'player_attack'} payload {id:string, name:string} */
  PLAYER_ATTACK: 'player_attack',
  /** @type {'skill_used'} payload {id:string, name:string} */
  SKILL_USED: 'skill_used',
  /** @type {'roll_start'} payload {id:string} */
  ROLL_START: 'roll_start',
  /** @type {'roll_end'} payload {id:string} */
  ROLL_END: 'roll_end',
  /** @type {'ally_down'} payload {id:string} */
  ALLY_DOWN: 'ally_down',
  /** @type {'ally_revive'} payload {id:string} */
  ALLY_REVIVE: 'ally_revive',
  /** @type {'ally_speech'} payload {id:string, text:{zh:string, en:string}} */
  ALLY_SPEECH: 'ally_speech',
  /** @type {'boss_hp'} payload BossHp */
  BOSS_HP: 'boss_hp',
  /** @type {'boss_attack'} payload {name:string, phase:number} */
  BOSS_ATTACK: 'boss_attack',
  /** @type {'telegraph_start'} payload TelegraphEvent */
  TELEGRAPH_START: 'telegraph_start',
  /** @type {'telegraph_resolve'} payload TelegraphEvent */
  TELEGRAPH_RESOLVE: 'telegraph_resolve',
  /** @type {'ending_trigger'} payload {id:'A'|'B'} */
  ENDING_TRIGGER: 'ending_trigger',
  /** @type {'theater_shot'} payload {endingId:string, id:string, index:number} */
  THEATER_SHOT: 'theater_shot',
  /** @type {'theater_done'} payload {endingId:string} */
  THEATER_DONE: 'theater_done',
  /** @type {'distill_progress'} payload {value:number} displayed 0–100 */
  DISTILL_PROGRESS: 'distill_progress',
  /** @type {'dario_line'} payload {event:string, text:{zh:string, en:string}, priority:number} */
  DARIO_LINE: 'dario_line',
  /** @type {'camera_shake'} payload {intensity:number, duration?:number} */
  CAMERA_SHAKE: 'camera_shake',
  /** @type {'pause'} payload {from:string} */
  PAUSE: 'pause',
  /** @type {'resume'} payload {} */
  RESUME: 'resume',
  /** @type {'select_confirm'} payload {charId:string} */
  SELECT_CONFIRM: 'select_confirm',
  /** @type {'retry'} payload {} */
  RETRY: 'retry',
  /** @type {'banner'} payload {phase:number, zh:string, en:string} */
  BANNER: 'banner',
  /** @type {'input_lock'} payload {locked:boolean, state:string} */
  INPUT_LOCK: 'input_lock',
  /** @type {'god_mode'} payload {enabled:boolean} */
  GOD_MODE: 'god_mode',
  /** @type {'lock_on'} payload {enabled:boolean} */
  LOCK_ON: 'lock_on',
  /** @type {'skill_silence'} payload {{duration:number, until:number, zh:string, en:string}} */
  SKILL_SILENCE: 'skill_silence',

  // --- v2 ---
  /** @type {'shot_fired'} payload {id:string, team:string, x:number, y:number} */
  SHOT_FIRED: 'shot_fired',
  /** @type {'bullet_spawn'} payload {team:string, x:number, y:number, shape?:string} */
  BULLET_SPAWN: 'bullet_spawn',
  /** @type {'skill_charge'} payload {id:string, t:number} */
  SKILL_CHARGE: 'skill_charge',
  /** @type {'skill_release'} payload {id:string, name?:string, ratio?:number} */
  SKILL_RELEASE: 'skill_release',
  /** @type {'shield_block'} payload {id:string, perfect:boolean, x:number, y:number} */
  SHIELD_BLOCK: 'shield_block',
  /** @type {'telegraph_end'} payload TelegraphEvent */
  TELEGRAPH_END: 'telegraph_end',
  /** @type {'phase_transition_start'} payload PhaseChange */
  PHASE_TRANSITION_START: 'phase_transition_start',
  /** @type {'phase_transition_end'} payload {phase:number} */
  PHASE_TRANSITION_END: 'phase_transition_end',
  /** @type {'safety_judgement'} payload {safeZones?:Array<{x:number,y:number,r:number}>} */
  SAFETY_JUDGEMENT: 'safety_judgement',
  /** @type {'cutscene_beat'} payload {id:string, beat:string, t?:number} */
  CUTSCENE_BEAT: 'cutscene_beat',
  /** @type {'vfx'} payload VfxRequest */
  VFX: 'vfx',
  /** @type {'shake'} payload {mag:number, dur:number} pixels, seconds */
  SHAKE: 'shake',
  /** @type {'flash'} payload {color:string, dur:number} */
  FLASH: 'flash',
});

/**
 * @typedef {Object} StateChange
 * @property {string|null} from
 * @property {string} to
 */

/**
 * @typedef {Object} PhaseChange
 * @property {1|2|3} phase
 * @property {number} [from]
 */

/**
 * @typedef {Object} HitEvent
 * @property {Actor|string|null} src
 * @property {Actor} dst
 * @property {number} dmg
 * @property {number} applied
 * @property {boolean} heavy
 */

/**
 * @typedef {Object} FlaskEvent
 * @property {string} type   'rtx5090' | 'h200' | 'b200'
 * @property {string} [id]
 */

/**
 * @typedef {Object} PlayerDeath
 * @property {number} phase
 * @property {string} [id]
 */

/**
 * @typedef {Object} BossHp
 * @property {number} ratio
 * @property {number} hp
 * @property {number} maxHp
 */

/** @typedef {'circle'|'sector'|'cone'|'line'|'ring'|'fullscreen'} TelegraphKind */

/**
 * @typedef {Object} TelegraphEvent
 * @property {string|null} attack
 * @property {TelegraphKind|string} shape
 * @property {string} id
 * @property {number} [duration]
 * @property {number} [x]
 * @property {number} [y]
 * @property {number} [r]
 */

/**
 * Pixel-space actor. `r` is the hurtbox radius, not the sprite size.
 * `invuln` is seconds of i-frames remaining. `facing` is an 8-way name
 * (`down`, `up`, `left`, `right`, `ne`, `nw`, `se`, `sw`) or a radians number.
 *
 * @typedef {Object} Actor
 * @property {string} id
 * @property {'player'|'ally'|'boss'|'neutral'} team
 * @property {number} x
 * @property {number} y
 * @property {number} vx
 * @property {number} vy
 * @property {number} r
 * @property {number} hp
 * @property {number} maxHp
 * @property {boolean} alive
 * @property {number} invuln
 * @property {string|number} facing
 * @property {string} sprite   Procedural / sheet id, e.g. `px.deepseek`.
 * @property {boolean} [rolling]
 * @property {number} [flash]
 * @property {boolean} [shield]
 * @property {number} [shieldAge]
 * @property {number} [superarmor]
 * @property {(info: DamageInfo) => void} [onHit]
 */

/**
 * @typedef {Actor & {
 *   phase: 1|2|3,
 *   lockHpAt25: boolean,
 *   commit: (opts?: {allowEnding?: boolean, debug?: boolean, noInvuln?: boolean}) => void,
 * }} BossActor
 */

/**
 * @typedef {Object} DamageInfo
 * @property {number} dmg
 * @property {number} [applied]
 * @property {boolean} [heavy]
 * @property {Actor|string|null} [src]
 * @property {string} [attackId]
 */

/**
 * Pooled projectile. Owned by actors/projectiles.js.
 *
 * @typedef {Object} Bullet
 * @property {boolean} alive
 * @property {'player'|'ally'|'boss'} team
 * @property {number} x
 * @property {number} y
 * @property {number} vx
 * @property {number} vy
 * @property {number} r
 * @property {number} dmg
 * @property {number} life
 * @property {string} [shape]
 * @property {string} [color]
 * @property {number} [pierce]
 * @property {number|boolean} [homing]
 * @property {number} [accel]
 * @property {number} [angularVel]
 * @property {number} [wobble]
 * @property {number} [knock]
 * @property {string} [attackId]
 * @property {string} [ownerId]
 * @property {(ctx: GameContext, bullet: Bullet, hit: Actor) => void} [onHit]
 */

/**
 * Ground warning in internal pixels. `t` on the debug snapshot is elapsed seconds.
 *
 * @typedef {Object} Telegraph
 * @property {string} id
 * @property {TelegraphKind|string} kind
 * @property {number} x
 * @property {number} y
 * @property {number} r
 * @property {number} elapsed
 * @property {number} duration
 * @property {string} [attack]
 * @property {number} [dirX]
 * @property {number} [dirY]
 * @property {number} [length]
 * @property {number} [width]
 * @property {number} [arc]
 * @property {Array<{x:number,y:number,r:number}>} [safeZones]
 * @property {boolean} alive
 * @property {(ctx: GameContext, tele: Telegraph) => void} [onResolve]
 */

/**
 * Generic juice request. `kind` is a short name (`num`, `spark`, `shock`, `slash`, `beam`, `muzzle`, `ring`).
 *
 * @typedef {Object} VfxRequest
 * @property {string} kind
 * @property {number} [x]
 * @property {number} [y]
 * @property {number} [x2]
 * @property {number} [y2]
 * @property {number} [r]
 * @property {number} [w]
 * @property {string} [color]
 * @property {string} [text]
 * @property {number} [life]
 * @property {number} [mag]
 * @property {number} [dur]
 */

/**
 * @typedef {Object} DebugFlags
 * @property {boolean} godMode
 * @property {boolean} showHitboxes
 * @property {number} playerDmgMul
 * @property {number} bossDmgMul
 * @property {number} allyDmgMul
 * @property {number} timeScale
 * @property {number} [camDistance]
 * @property {number} [camHeight]
 * @property {number} [camSide]
 * @property {number} [camFov]
 */

/**
 * @typedef {Object} StateMachine
 * @property {string} current
 * @property {string|null} previous
 * @property {(next: string) => void} set
 */

/**
 * @typedef {Object} InputAPI
 * @property {(name: string) => boolean} pressed
 * @property {(name: string) => boolean} held
 * @property {(name: string) => void} eat
 * @property {() => boolean} typing
 * @property {{x:number, y:number, clientX:number, clientY:number, dx:number, dy:number, onUi:boolean}} pointer
 * @property {(player: Actor|null|undefined) => {x:number, y:number}|null} aimVector
 * @property {(fn: (clientX:number, clientY:number) => {x:number, y:number}) => void} setMapper
 * @property {(open: boolean) => void} setEdgesOpen
 * @property {() => void} endFrame
 * @property {() => void} attach
 */

/**
 * @typedef {Object} AudioAPI
 * @property {(id: string, opts?: object) => void} playSfx
 * @property {(id: string, fade?: number|object) => void} playBgm
 * @property {(fade?: number|object) => void} stopBgm
 * @property {(id: string, opts?: object) => {duration:number, promise:Promise<number>}} playVo
 * @property {() => void} stopVo
 * @property {(id?: string, fade?: number|object) => void} stopSfx
 * @property {(amount?: number|boolean) => void} duck
 * @property {(partial: {master?:number, music?:number, sfx?:number, vo?:number}) => void} setVolume
 * @property {() => {master:number, music:number, sfx:number, vo:number}} getVolume
 * @property {() => void} unlock
 * @property {(ctx: GameContext) => void} init
 * @property {(ctx: GameContext, dt: number) => void} update
 */

/**
 * @typedef {Object} TimeAPI
 * @property {number} fixedDt
 * @property {number} timeScale
 * @property {number} elapsed
 * @property {number} unscaled
 * @property {number} lastRaw
 * @property {boolean} paused
 * @property {number} hitStop   Seconds of sim freeze remaining. Not a method.
 * @property {(ms: number) => void} requestHitStop   Pass milliseconds. Do not add a method named hitStop.
 * @property {(scale: number) => void} setScale
 * @property {(on: boolean) => void} setPaused
 * @property {() => void} reset
 * @property {(rawDt: number, opts?: {freeze?: boolean}) => number[]} consume
 */

/**
 * @typedef {Object} AssetAPI
 * @property {(id: string) => string|null} get
 * @property {(id: string) => HTMLImageElement|null} image
 * @property {object} config
 */

/**
 * @typedef {Object} WorldAPI
 * @property {(actor: Actor) => void} clamp
 * @property {(zh: string, en: string) => void} setHolo
 * @property {object} [room]
 * @property {object} [vfx]
 * @property {object} [telegraph]
 * @property {object} [sprites]
 */

/**
 * @typedef {Object} GameContext
 * @property {import('./bus.js').EventBus} bus
 * @property {InputAPI} input
 * @property {AudioAPI} audio
 * @property {TimeAPI} time
 * @property {AssetAPI} assets
 * @property {Actor|null} player
 * @property {BossActor|null} boss
 * @property {Actor[]} allies
 * @property {Actor|null} [stele]
 * @property {WorldAPI} world
 * @property {StateMachine} state
 * @property {DebugFlags} debug
 * @property {string|null} selectedChar
 * @property {boolean} lockOn
 * @property {'A'|'B'|null} endingActive
 * @property {number} distill
 * @property {number} endingDistill
 * @property {{A?:boolean, B?:boolean}} endingsUnlocked
 * @property {{skillSilence?: number, skillSilenceUntil?: number, contentPolicySilence?: boolean, inputLocked?: boolean}} flags
 * @property {number} [truceUntil]
 * @property {string|null} [pauseFrom]
 * @property {string|null} [theaterShot]
 * @property {{id:string, beat:string, t:number}|null} [cutscene]
 * @property {{zh:string, en:string, until:number}|null} [holo]
 * @property {(id: string) => void} startFight
 * @property {() => void} retry
 * @property {() => void} goTitle
 * @property {() => void} [finishIntro]
 */

/**
 * Sim modules: `update(ctx, dt)` with a fixed, already-scaled step.
 * Draw modules: `render(ctx, g)` into the 480×270 buffer.
 *
 * @typedef {Object} GameModule
 * @property {(ctx: GameContext) => void} [init]
 * @property {(ctx: GameContext, dt: number) => void} [update]
 * @property {(ctx: GameContext, g: CanvasRenderingContext2D) => void} [render]
 * @property {(ctx: GameContext) => void} [reset]
 */
